def receipt_covers_target(receipt, paths, digests):
    """A receipt covers the request's target only if the materials manifest it signed
    enumerates this exact package build and this exact deployment configuration."""
    try:
        raw = (ROOT / receipt["materials_path"]).read_bytes()
    except (OSError, KeyError, TypeError):
        return False, "materials file missing or unreadable"
    if hashlib.sha256(raw).hexdigest() != receipt["signed_statement"].get("materials_sha256"):
        return False, "materials file does not hash to the signed materials_sha256"
    entries = {m.get("path"): m.get("sha256")
               for m in json.loads(raw).get("materials", [])}
    for path, want in zip(paths, digests):
        if entries.get(path) != want:
            return False, "signed materials list %s under a different digest (%s), target has %s" % (
                path, (entries.get(path) or "no entry")[:16], want[:16])
    return True, "signed materials cover the current package and configuration""}
